  return JSON.parse(fs.readFileSync(FLAGD_CONFIG_PATH, 'utf-8'));
}

function writeConfig(config: any) {
  fs.writeFileSync(FLAGD_CONFIG_PATH, JSON.stringify(config, null, 2));
}

export async function setFlag(flagName: string, variant: string): Promise<void> {
  const config = readConfig();
  if (!config.flags[flagName]) {
    throw new Error(`Unknown flag "${flagName}" — check src/flagd/demo.flagd.json`);
  }
  config.flags[flagName].defaultVariant = variant;
  writeConfig(config);
  await new Promise((r) => setTimeout(r, FLAGD_RELOAD_DELAY_MS));
}

export async function resetFlag(flagName: string): Promise<void> {
  await setFlag(flagName, 'off');
}

/** Snapshot + restore, so a failing assertion mid-test never leaves a flag stuck on for later tests. */
export function withFlagCleanup(flagNames: string[]) {
  let original: string;
  return {
    async before() {
      original = fs.readFileSync(FLAGD_CONFIG_PATH, 'utf-8');
    },
    async after() {
      fs.writeFileSync(FLAGD_CONFIG_PATH, original);
      await new Promise((r) => setTimeout(r, FLAGD_RELOAD_DELAY_MS));
    },
  };
}

